def solve(G, border, fill):
    H, W = len(G), len(G[0])
    sr = [i for i in range(H) if all(c != fill for c in G[i])]
    sc = [j for j in range(W) if all(G[i][j] != fill for i in range(H))]
    marks = {(i, j): G[i][j] for i in sr for j in sc if G[i][j] != border}
    bb = {}
    for (i, j), c in marks.items():
        b = bb.get(c)
        if b is None: bb[c] = [i, i, j, j]
        else:
            b[0]=min(b[0],i); b[1]=max(b[1],i); b[2]=min(b[2],j); b[3]=max(b[3],j)
    hs = [i for i in sr if marks and min(m[0] for m in marks) <= i <= max(m[0] for m in marks)]
    vs = [j for j in sc if min(m[1] for m in marks) <= j <= max(m[1] for m in marks)]
    out = []
    for k in range(len(hs)-1):
        r0, r1 = hs[k], hs[k+1]
        row = []
        for l in range(len(vs)-1):
            c0, c1 = vs[l], vs[l+1]
            col = fill
            for color, (a0, a1, b0, b1) in bb.items():
                if r0 >= a0 and r1 <= a1 and c0 >= b0 and c1 <= b1:
                    col = color
            row.append(col)
        out.append(row)
    return out

